import{_ as r,a0 as e,w as s,s as u,I as p,x as o,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"解密 top 命令 | LCTT x X-CMD","titleTemplate":false,"description":"解密 top 命令 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"解密 top 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"解密 top 命令 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Deciphering Top","title":"解密 top 命令","tag":"201311","desc":""},"relativePath":"201311/Deciphering Top.md","filePath":"[post].md"}'),m={name:"201311/Deciphering Top.md"};function d(a,t,f,C,g,T){const l=e("Link");return s(),u("div",null,[t[15]||(t[15]=p("h1",{id:"解密-top-命令",tabindex:"-1"},[o('解密"top"命令 '),p("a",{class:"header-anchor",href:"#解密-top-命令","aria-label":"Permalink to “解密top命令”"},"​")],-1)),t[16]||(t[16]=p("p",null,'當對服務器的性能好奇時，我第一個想到的是"top"命令。top不是最好的，它不是一個長期的快照，但是它提供了服務器的一個不錯的時間點快照，並且試着提供了告訴"現在在發生什麼？"。不幸地，如果你沒有深入瞭解不同顯示域的意義，top的輸出很容易被誤解。',-1)),p("p",null,[t[1]||(t[1]=o("我不會完整解讀top命令的",-1)),n(l,{href:"http://www.linuxmanpages.com/man1/top1.php"},{default:i(()=>[...t[0]||(t[0]=[o("man page",-1)])]),_:1}),t[2]||(t[2]=o("，當你和時間和意願時，它一直在那等着你。我想要做的是指出一些我如何得到系統的快速概況的幾個要點，並希望得到我接下來該怎麼做的指示。top是我在故障排除時的第一站，但這很少會是我唯一的一站。",-1))]),p("p",null,[n(l,{href:"http://www.flickr.com/photos/51724787@N06/10847969205/"},{default:i(()=>[...t[3]||(t[3]=[p("img",{src:"http://farm4.staticflickr.com/3827/10847969205_5005a709c2_o.png",alt:""},null,-1)])]),_:1})]),t[17]||(t[17]=p("p",null,'top命令我第一個看的是平均負載(load average)，它在右上角的屏幕上。平均負載的計算是基於統計蒐集到的數量，但是通常可以認為是CPU被請求工作的數量。如果你的機器有一個單核CPU，那麼平均負載是1就意味着機器滿載的，並且有足夠的能力在採樣時間內完成任務。同樣地，如果平均負載是2，那對單核的CPU是超載的，並需要2個可用內核才能在同樣的採樣時間內完成的要求的任務。隨着8、16、32核的發售，我會在判斷平均負載的時候就要注意一下。比如我需要去檢測時，我會在top裏按了數字"1"，這會列出所有CPU核列表，這樣我就可以得到一個快速計數用於比較負載。',-1)),t[18]||(t[18]=p("p",null,'我檢查的第二項是上面列出來的內容的第9列，標記着"%CPU"那個。對這一列的解釋是很模糊的:',-1)),t[19]||(t[19]=p("blockquote",null,[p("p",null,"任務所分享的上次屏幕刷新後的CPU運行時間，以全部的CPU時間百分比表示。在一個真正的SMP（多處理器）環境中，如果'Irix mode'是關閉的，top會在'Solaris mode'下運行，這裏一個任務的cpu使用率將除以全部的CPU數量。你可以用'I'（大寫字母I）這個交互命令觸發Irix或Solaris模式。")],-1)),t[20]||(t[20]=p("p",null,"一點也不清楚，是麼？這裏要記住的主要意思是，如果單個進程由於某個原因或者其他因素佔用率升高，那麼他很有可能會以%CPU很高的數字顯示在top的第一行。",-1)),t[21]||(t[21]=p("p",null,'我下一個注意到的區域是"Cpu(s):"這一行，在頭部信息的中間。特別地，我對%us、sy%、%id、和%wa感興趣，它們分別是用户進程、系統進程、空閒時間和CPU用於等待I/O流執行的時間比例。這個百分比應該接近於0，高於5%時需要密切關注。',-1)),t[22]||(t[22]=p("p",null,"最後，我想要看看系統up時間，這顯示在左上角。如果我對一台服務器有疑問，並且這台服務器最近重啓過，這裏可能會發現一些什麼，或許是一個守護進程沒有啓動。",-1)),t[23]||(t[23]=p("p",null,"這些檢查只需要幾秒。如果我只是觀察，我可能讓top運行幾分鐘並觀察進程、CPU和負載，但是通常地我很快地進入和退出top。top是給你一個系統健康概況的那些奇妙系統管理員工具之一，並允許你快速診斷潛在的問題。",-1)),t[24]||(t[24]=p("hr",null,null,-1)),p("p",null,[t[5]||(t[5]=o("via: ",-1)),n(l,{href:"http://ostatic.com/blog/deciphering-top"},{default:i(()=>[...t[4]||(t[4]=[o("http://ostatic.com/blog/deciphering-top",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=o("譯者：",-1)),n(l,{href:"https://github.com/geekpi"},{default:i(()=>[...t[6]||(t[6]=[o("geekpi",-1)])]),_:1}),t[9]||(t[9]=o(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=o("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原創翻譯，",-1)),n(l,{href:"http://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[o("Linux中國",-1)])]),_:1}),t[14]||(t[14]=o(" 榮譽推出",-1))])])}const U=r(m,[["render",d]]);export{w as __pageData,U as default};
